    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Tiếng Việt có thể bỏ \"là\" (Tôi sinh viên), nhưng tiếng Anh không bao giờ được bỏ be trong câu kiểu này."
        },
        "examples": [
          {
            "target": "I am a student.",
            "translation": {
              "vi": "Tôi là sinh viên."
            }
          },
          {
            "target": "They are teachers.",
            "translation": {
              "vi": "Họ là giáo viên."
            }
          }
        ],
        "meaning": {
          "vi": "là, thì, ở: I → am; he, she, it → is; you, we, they → are"
