      "difficulty": 4,
      "front": {
        "pos": "câu hỏi đuôi",
        "text": "…, isn't it? / …, don't you? / …, didn't they? (question tags)"
      },
      "id": "d419b6d7-fa77-5e66-852e-a2b901a7ce7c",
      "is_demo": false,
      "item_type": "grammar_point",
      "key": "en:item:question-tags",
      "language_code": "en",
      "level_code": "b1",
