      "id": "e0a0d6dc-30fc-55d1-a242-f9c0bdec8f25",
      "is_demo": false,
      "item_type": "grammar_point",
      "key": "ko:item:ha-gram-eul-jeongdoro",
      "language_code": "ko",
      "level_code": "topik3",
