      "estimated_minutes": 18,
      "id": "d58b47e1-8bbb-5703-9d0a-9e7091fd9086",
      "is_demo": false,
      "key": "en:lesson:everyday-now-review",
      "language_code": "en",
      "level_code": "a2",
      "objectives": [
        {
          "vi": "Theo dõi trọn một cuộc gọi công việc - hỏi gặp, để lại lời nhắn, gọi lại và chốt lịch hẹn."
        },
        {
